<script>
document.addEventListener('DOMContentLoaded',()=>{
    const banner=document.querySelector('.event-banner');
    if(!banner || banner.closest('.event-banner-card')) return;
    const slides=@json($bannerSlides);
    if(slides.length){
        const safe=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[char]));
        const carouselItems=slides.map((slide,index)=>`<div class="carousel-item ${index===0?'active':''}">${slide.type==='video'?`<video src="${safe(slide.src)}" autoplay muted loop playsinline></video>`:`<img src="${safe(slide.src)}" alt="${safe(slide.title||'Webinar banner')}">`}<span class="banner-slide-caption">${safe(slide.title||@json($webinar->title))}</span></div>`).join('');
        const indicators=slides.length>1?`<div class="carousel-indicators">${slides.map((_,index)=>`<button type="button" data-bs-target="#webinarBannerCarousel" data-bs-slide-to="${index}" class="${index===0?'active':''}" aria-label="Banner ${index+1}"></button>`).join('')}</div>`:'';
        const controls=slides.length>1?'<button class="carousel-control-prev" type="button" data-bs-target="#webinarBannerCarousel" data-bs-slide="prev"><span class="carousel-control-prev-icon"></span><span class="visually-hidden">Previous</span></button><button class="carousel-control-next" type="button" data-bs-target="#webinarBannerCarousel" data-bs-slide="next"><span class="carousel-control-next-icon"></span><span class="visually-hidden">Next</span></button>':'';
        banner.innerHTML=`<div id="webinarBannerCarousel" class="carousel slide" data-bs-ride="carousel" data-bs-interval="5000" data-bs-pause="false" data-bs-wrap="true">${indicators}<div class="carousel-inner">${carouselItems}</div>${controls}<div class="carousel-progress"><span></span></div></div><span class="live-pill"><b></b> {{ strtoupper($webinar->status) }}</span>`;
        if(slides.length>1){bootstrap.Carousel.getOrCreateInstance(banner.querySelector('#webinarBannerCarousel'),{interval:5000,pause:false,wrap:true}).cycle();}
    }
    const card=document.createElement('div');
    card.className='event-banner-card';
    banner.parentNode.insertBefore(card,banner);
    card.appendChild(banner);
    const rail=document.createElement('div');
    rail.className='banner-event-rail';
    rail.innerHTML=`
        <div class="banner-event-detail"><i class="bi bi-calendar3"></i><span><strong>{{ $webinar->starts_at?->timezone($webinar->timezone)->format('M d, Y') ?: 'Date to be announced' }}</strong><small>Event date</small></span></div>
        <div class="banner-event-detail"><i class="bi bi-clock"></i><span><strong>{{ $webinar->starts_at?->timezone($webinar->timezone)->format('g:i A') ?: 'Time to be announced' }}</strong><small>{{ $webinar->timezone }}</small></span></div>
        <div class="banner-event-detail"><i class="bi bi-alarm-fill"></i><span><small class="banner-timer-label">STARTS IN</small><strong data-banner-countdown>{{ $webinar->status === 'live' ? 'Live now' : ucfirst($webinar->status) }}</strong></span></div>
        @if($webinar->speakers->isNotEmpty())<div class="banner-speakers"><i class="bi bi-mic"></i><strong>Speakers:</strong><span>{{ $webinar->speakers->pluck('name')->join(', ') }}</span></div>@endif`;
    card.appendChild(rail);
    const shareUrl=encodeURIComponent(window.location.href);
    const shareText=encodeURIComponent(@json($webinar->title));
    const googleCalendar=@json('https://calendar.google.com/calendar/render?action=TEMPLATE&text='.rawurlencode($webinar->title).'&dates='.($webinar->starts_at?->copy()->utc()->format('Ymd\THis\Z')??'').'/'.($webinar->ends_at?->copy()->utc()->format('Ymd\THis\Z')??'').'&details='.rawurlencode($webinar->short_description?:$webinar->description).'&location='.rawurlencode($webinar->venue?:'Online'));
    const actions=document.createElement('div');
    actions.className='event-action-bar';
    actions.innerHTML=`<a href="${googleCalendar}" target="_blank" rel="noopener"><i class="bi bi-calendar-plus"></i>Add to Calendar</a><a href="https://wa.me/?text=${shareText}%20${shareUrl}" target="_blank" rel="noopener"><i class="bi bi-whatsapp"></i>WhatsApp</a><a href="https://www.linkedin.com/sharing/share-offsite/?url=${shareUrl}" target="_blank" rel="noopener"><i class="bi bi-linkedin"></i>LinkedIn</a><button type="button" data-copy-event-link><i class="bi bi-link-45deg"></i><span>Copy Link</span></button>`;
    card.appendChild(actions);
    actions.querySelector('[data-copy-event-link]').addEventListener('click',async event=>{await navigator.clipboard.writeText(window.location.href);event.currentTarget.querySelector('span').textContent='Copied';setTimeout(()=>event.currentTarget.querySelector('span').textContent='Copy Link',1600)});
    const carouselElement=banner.querySelector('#webinarBannerCarousel');
    carouselElement?.addEventListener('slide.bs.carousel',()=>banner.querySelectorAll('video').forEach(video=>video.pause()));
    carouselElement?.addEventListener('slid.bs.carousel',()=>{banner.querySelector('.carousel-item.active video')?.play().catch(()=>{});const progress=banner.querySelector('.carousel-progress span');if(progress){progress.style.animation='none';void progress.offsetWidth;progress.style.animation='bannerProgress 5s linear infinite';}});
    const countdown=rail.querySelector('[data-banner-countdown]');
    @if($webinar->starts_at && !in_array($webinar->status,['live','completed','cancelled']))
    const startAt=new Date(@json($webinar->starts_at->copy()->utc()->toIso8601String())).getTime();
    const updateBannerTimer=()=>{
        const distance=startAt-Date.now();
        if(distance<=0){countdown.textContent='Starting now';return;}
        const days=Math.floor(distance/86400000),hours=Math.floor((distance%86400000)/3600000),minutes=Math.floor((distance%3600000)/60000),seconds=Math.floor((distance%60000)/1000);
        countdown.className='banner-timer-units';
        countdown.innerHTML=`<span class="banner-timer-unit"><b>${String(days).padStart(2,'0')}</b><em>DAYS</em></span><span class="banner-timer-unit"><b>${String(hours).padStart(2,'0')}</b><em>HOURS</em></span><span class="banner-timer-unit"><b>${String(minutes).padStart(2,'0')}</b><em>MIN</em></span><span class="banner-timer-unit"><b>${String(seconds).padStart(2,'0')}</b><em>SEC</em></span>`;
    };
    updateBannerTimer(); setInterval(updateBannerTimer,1000);
    @endif
    const speakerProfiles=@json($speakerProfiles);
    if(speakerProfiles.length){
        const escapeProfile=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[char]));
        const profileModal=document.createElement('div');
        profileModal.className='modal fade speaker-detail-modal';
        profileModal.id='speakerDetailModal';
        profileModal.tabIndex=-1;
        profileModal.innerHTML='<div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header border-0 position-absolute end-0 top-0 z-3"><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div data-speaker-detail></div></div></div>';
        document.body.appendChild(profileModal);
        document.querySelectorAll('.speaker-profile').forEach((card,index)=>{
            const profile=speakerProfiles[index];
            if(!profile) return;
            const button=document.createElement('button');
            button.type='button';button.className='speaker-profile-button';button.innerHTML='<i class="bi bi-person-vcard me-1"></i> View Full Profile';
            card.querySelector('.speaker-info')?.appendChild(button);
            button.addEventListener('click',()=>{
                const initials=profile.name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();
                const photo=profile.photo?`<img src="${escapeProfile(profile.photo)}" alt="${escapeProfile(profile.name)}">`:`<div class="speaker-detail-avatar">${escapeProfile(initials)}</div>`;
                profileModal.querySelector('[data-speaker-detail]').innerHTML=`<div class="speaker-detail-hero">${photo}</div><div class="modal-body"><h2>${escapeProfile(profile.name)}</h2>${profile.headline?`<div class="speaker-detail-role">${escapeProfile(profile.headline)}</div>`:''}${profile.company?`<div class="speaker-detail-company">${escapeProfile(profile.company)}</div>`:''}<div class="speaker-detail-bio">${escapeProfile(profile.bio||'Speaker profile details will be available soon.')}</div></div>`;
                bootstrap.Modal.getOrCreateInstance(profileModal).show();
            });
        });
    }
    @guest
    const mobileCta=document.createElement('div');
    mobileCta.className='mobile-event-cta';
    mobileCta.innerHTML='<button type="button" class="btn btn-gradient" data-bs-toggle="modal" data-bs-target="#micrositeRegisterModal">Register Now</button><button type="button" class="btn btn-outline-primary" data-mobile-login>Login</button>';
    document.body.appendChild(mobileCta);
    mobileCta.querySelector('[data-mobile-login]')?.addEventListener('click',()=>bootstrap.Modal.getOrCreateInstance(document.querySelector('#micrositeLoginModal')).show());
    @endguest
});
</script>
@endif
